mapper.select:
SELECT page_id::TEXT AS db_key, title, use_yn FROM t_page WHERE use_yn = 'Y'
AND title LIKE '%' || #{searchKeyword} || '%'
ORDER BY page_id DESC LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE t_page SET title = #{title}, context = #{context},
    upd_id = #{updId}, upd_dt = NOW(), upd_ip = #{updIp}
WHERE page_id = #{dbKey}::integer
